use vstd::prelude::*;

verus! {
    // Specification for the split_and_append function
    fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
        requires
            0 < n && n < list.len(),
        ensures
            new_list.len() == list.len() &&
            new_list[..(list.len() - n)] == list[n..] &&
            new_list[(list.len() - n)..] == list[..n],
    {
        let len = list.len();
        let mut new_list: Vec<i32> = Vec::new();
        
        // Append the subarray from index n to the end
        for i in n..len
            invariant
                new_list.len() == i - n,
                new_list.len() <= len,
        {
            new_list.push(list[i]);
        }

        // Append the subarray from index 0 to n
        for i in 0..n
            invariant
                new_list.len() == len - n + i,
                new_list.len() <= len,
        {
            new_list.push(list[i]);
        }

        new_list
    }
}

